class Node:
    """Represents a node in the red-black tree."""
    def __init__(self, key, color, left=None, right=None, parent=None):
        self.key = key
        self.color = color
        self.left = left
        self.right = right
        self.parent = parent

class RedBlackTree:
    """Represents a red-black tree."""
    def __init__(self):
        self.NIL = Node(None, 'black')
        self.root = self.NIL

    def _left_rotate(self, x):
        """Rotates node x to the left."""
        y = x.right
        x.right = y.left
        if y.left != self.NIL:
            y.left.parent = x
        y.parent = x.parent
        if x.parent == None:
            self.root = y
        elif x == x.parent.left:
            x.parent.left = y
        else:
            x.parent.right = y
        y.left = x
        x.parent = y

    def _right_rotate(self, x):
        """Rotates node x to the right."""
        y = x.left
        x.left = y.right
        if y.right != self.NIL:
            y.right.parent = x
        y.parent = x.parent
        if x.parent == None:
            self.root = y
        elif x == x.parent.right:
            x.parent.right = y
        else:
            x.parent.left = y
        y.right = x
        x.parent = y

    def _fix_insert(self, k):
        """Fixes the tree after insertion."""
        while k.parent.color == 'red':
            if k.parent == k.parent.parent.left:
                u = k.parent.parent.right
                if u.color == 'red':
                    u.color = 'black'
                    k.parent.color = 'black'
                    k.parent.parent.color = 'red'
                    k = k.parent.parent
                else:
                    if k == k.parent.right:
                        k = k.parent
                        self._left_rotate(k)
                    k.parent.color = 'black'
                    k.parent.parent.color = 'red'
                    self._right_rotate(k.parent.parent)
            else:
                u = k.parent.parent.left
                if u.color == 'red':
                    u.color = 'black'
                    k.parent.color = 'black'
                    k.parent.parent.color = 'red'
                    k = k.parent.parent
                else:
                    if k == k.parent.left:
                        k = k.parent
                        self._right_rotate(k)
                    k.parent.color = 'black'
                    k.parent.parent.color = 'red'
                    self._left_rotate(k.parent.parent)
            if k == self.root:
                break
        self.root.color = 'black'

    def _insert(self, key, node):
        """Inserts a new node with the given key."""
        if node == self.NIL:
            return Node(key, 'red')
        elif key < node.key:
            node.left = self._insert(key, node.left)
            node.left.parent = node
        elif key > node.key:
            node.right = self._insert(key, node.right)
            node.right.parent = node
        return node

    def insert(self, key):
        """Inserts a new node with the given key."""
        node = self._insert(key, self.root)
        if node != self.root:
            node.parent.color = 'black'
        else:
            node.color = 'black'

        # Fix the tree after insertion
        self._fix_insert(node)

    def pre_order(self):
        """Prints the tree in pre-order traversal."""
        self._pre_order(self.root)

    def _pre_order(self, node):
        """Recursive helper function for pre-order traversal."""
        if node != self.NIL:
            print(f"Key: {node.key}, Color: {node.color}")
            self._pre_order(node.left)
            self._pre_order(node.right)

    def in_order(self):
        """Prints the tree in in-order traversal."""
        self._in_order(self.root)

    def _in_order(self, node):
        """Recursive helper function for in-order traversal."""
        if node != self.NIL:
            self._in_order(node.left)
            print(f"Key: {node.key}, Color: {node.color}")
            self._in_order(node.right)

    def post_order(self):
        """Prints the tree in post-order traversal."""
        self._post_order(self.root)

    def _post_order(self, node):
        """Recursive helper function for post-order traversal."""
        if node != self.NIL:
            self._post_order(node.left)
            self._post_order(node.right)
            print(f"Key: {node.key}, Color: {node.color}")

